+// Sales from the till. Each dish sold uses one portion of its recipe per
+// `qty`; the ingredients are consumed with ref `sale:<ticket>`. A ticket is
+// imported once; importing is all or nothing.
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getItem, onHand } from "./items.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** True when a ticket has already been imported. */
+export function ticketImported(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/**
+ * Records sale lines [{ row, ticket, soldAt, dishId, qty }] and consumes their
+ * ingredients. Lines of tickets already imported are skipped. Checks stock for
+ * every line first; throws import_stock naming the first row that runs out.
+ * Returns { tickets, dishes } imported.
+ */
+export function recordSales(store, lines) {
+  const fresh = lines.filter((l) => !ticketImported(store, l.ticket));
+  const planned = fresh.map((l) => {
+    const dish = (store.data.dishes ?? []).find((d) => d.id === l.dishId);
+    if (!dish) throw new AppError("bad_request", { reason: `row ${l.row}: unknown dish ${l.dishId}` });
+    const uses = scaled(getRecipe(store, dish.recipeId), l.qty).filter((u) => u.qty > 0);
+    return { ...l, uses };
+  });
+  const needed = new Map();
+  for (const p of planned) {
+    for (const u of p.uses) {
+      const need = round3((needed.get(u.itemId) ?? 0) + u.qty);
+      const available = round3(onHand(store, u.itemId));
+      if (need > available) {
+        const item = getItem(store, u.itemId);
+        const left = round3(available - (needed.get(u.itemId) ?? 0));
+        throw new AppError("import_stock", { row: p.row, item: item.name, available: left, unit: item.unit });
+      }
+      needed.set(u.itemId, need);
+    }
+  }
+  store.data.sales ??= [];
+  for (const p of planned) {
+    store.data.sales.push({ id: store.nextId("sale"), ticket: p.ticket, soldAt: p.soldAt, dishId: p.dishId, qty: p.qty, uses: p.uses });
+    for (const u of p.uses) consume(store, u.itemId, u.qty, { at: p.soldAt, ref: `sale:${p.ticket}` });
+  }
+  return {
+    tickets: new Set(planned.map((p) => p.ticket)).size,
+    dishes: planned.reduce((s, p) => s + p.qty, 0),
+  };
+}
